diff --git a/tests/proxy-partners.test.ts b/tests/proxy-partners.test.ts
new file mode 100644
index 00000000..a5bca398
--- /dev/null
+++ b/tests/proxy-partners.test.ts
@@ -0,0 +1,36 @@
+import { beforeAll, describe, expect, it } from "vitest";
+import { NextRequest } from "next/server";
+import { proxy } from "../proxy";
+import { CLIENT_COOKIE } from "../lib/client-auth-edge";
+
+const SECRET = "test-only-session-secret-not-used-in-prod-0123456789";
+
+async function mintClientCookie(slug: string): Promise<string> {
+  const payload = btoa(JSON.stringify({ method: "client", slug, issuedAt: Date.now() }));
+  const key = await crypto.subtle.importKey(
+    "raw",
+    new TextEncoder().encode(SECRET),
+    { name: "HMAC", hash: "SHA-256" },
+    false,
+    ["sign"],
+  );
+  const mac = new Uint8Array(await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(payload)));
+  return `${payload}.${Array.from(mac, (b) => b.toString(16).padStart(2, "0")).join("")}`;
+}
+
+beforeAll(() => {
+  process.env.SESSION_SECRET = SECRET;
+});
+
+describe("proxy() gate on /partners", () => {
+  it("redirects to /client/login without a session and passes with one", async () => {
+    const url = "https://solaisoft.com/partners/anything";
+    const denied = await proxy(new NextRequest(url));
+    expect(denied.headers.get("location") || "").toContain("/client/login");
+
+    const cookie = await mintClientCookie("station-street-fitness");
+    const headers = new Headers({ cookie: `${CLIENT_COOKIE}=${cookie}` });
+    const ok = await proxy(new NextRequest(url, { headers }));
+    expect(ok.headers.get("location")).toBeNull();
+  });
+});
